'use strict';

/**
 * Source: researched attribute dictionary and per-shop-type attribute sets —
 *   seeds/attributes/definitions.json → attribute_definitions
 *   seeds/attributes/sets.json        → attribute_sets (node shop_type:<sub-category key>)
 * Both files are generated by `node attributes/build.js` from attributes/research/*.json.
 * Run after curated-taxonomy: every set references a shop_type node.
 */

const path = require('path');
const fs = require('fs');
const { sha256, sha256File } = require('../../lib/hash');
const { cleanText } = require('../../lib/text');
const { assertActiveReferences } = require('../../lib/loader');

const SOURCE = 'attribute-sets';
const FILES = ['attributes/definitions.json', 'attributes/sets.json'];
const KEY = /^[a-z][a-z0-9_]{0,39}$/;
const TYPES = new Set(['text', 'textarea', 'number', 'boolean', 'date', 'enum', 'multi_enum', 'measure']);
const UNIT_FAMILIES = new Set([
  'mass', 'volume', 'length', 'area', 'power', 'energy', 'data', 'duration', 'count',
  'temperature', 'currency', 'percent',
]);
const LEVELS = new Set(['statutory', 'required', 'recommended', 'optional']);
const OWNERS = new Set(['catalog', 'store']);

const meta = {
  name: SOURCE,
  title: 'Researched attribute dictionary and attribute sets per shop type',
  license: 'Internal (research citations kept per attribute)',
  transformVersion: 1,
  maxRejectRatio: 0,
};

const entities = [
  {
    table: 'attribute_definitions',
    key: ['key'],
    columns: [
      'key', 'label', 'type', 'unit_family', 'default_unit', 'values', 'open_values',
      'description', 'shopify_handle', 'ondc_attribute', 'sources', 'source',
    ],
    scope: `t.source = '${SOURCE}'`,
    maxDeactivateRatio: 0.2,
  },
  {
    table: 'attribute_sets',
    key: ['node_id', 'attribute_key'],
    columns: [
      'node_id', 'attribute_key', 'level', 'owner', 'per_variant', 'filterable', 'axis_order',
      'in_basic_form', 'sort_order', 'note', 'source',
    ],
    scope: `t.source = '${SOURCE}'`,
    maxDeactivateRatio: 0.2,
    beforeUpsert: assertActiveReferences(SOURCE, [
      { column: 'node_id', table: 'taxonomy_nodes', key: 'id' },
      { column: 'attribute_key', table: 'attribute_definitions', key: 'key' },
    ]),
  },
];

async function extract(ctx) {
  const files = FILES.map((f) => path.join(ctx.config.seedDir, f));
  const shas = await Promise.all(files.map((f) => sha256File(f)));
  const read = (f) => JSON.parse(fs.readFileSync(f, 'utf8'));
  return {
    version: 'seed',
    inputSha256: sha256(shas.join(':')),
    definitions: read(files[0]),
    sets: read(files[1]),
  };
}

const bool = (v) => v === true;
const textOrNull = (v) => cleanText(v) || null;

function transform(input) {
  const rejects = [];
  const bad = (entity, key, reason, raw) => rejects.push({ entity, source_key: key, reason, raw });

  const definitions = [];
  const known = new Set();
  for (const [key, d] of Object.entries(input.definitions || {})) {
    const type = d && d.type;
    const unitFamily = d && d.unit_family ? d.unit_family : null;
    const values = Array.isArray(d && d.values) ? d.values.map((v) => cleanText(String(v))).filter(Boolean) : [];
    let reason = null;
    if (!KEY.test(key)) reason = 'bad_key';
    else if (!cleanText(d && d.label)) reason = 'empty_label';
    else if (!TYPES.has(type)) reason = `bad_type:${type}`;
    else if (unitFamily && !UNIT_FAMILIES.has(unitFamily)) reason = `bad_unit_family:${unitFamily}`;
    else if ((type === 'measure') !== Boolean(unitFamily)) reason = 'measure_needs_unit_family';
    else if ((type === 'enum' || type === 'multi_enum') && !values.length && !d.open_values) reason = 'enum_without_values';
    if (reason) {
      bad('attribute_definitions', key, reason, d);
      continue;
    }
    known.add(key);
    definitions.push({
      key,
      label: cleanText(d.label),
      type,
      unit_family: unitFamily,
      default_unit: textOrNull(d.default_unit),
      values: [...new Set(values)],
      open_values: bool(d.open_values),
      description: textOrNull(d.description),
      shopify_handle: textOrNull(d.shopify_handle),
      ondc_attribute: textOrNull(d.ondc_attribute),
      sources: Array.isArray(d.sources) ? d.sources : [],
      source: SOURCE,
    });
  }

  const sets = [];
  for (const [subKey, s] of Object.entries(input.sets || {})) {
    const nodeId = `shop_type:${subKey}`;
    const axes = Array.isArray(s.variant_axes) ? s.variant_axes : [];
    const basic = new Set(Array.isArray(s.basic_form) ? s.basic_form : []);
    const seen = new Set();
    (s.attributes || []).forEach((a, i) => {
      const k = `${subKey}.${a && a.key}`;
      let reason = null;
      if (!a || !known.has(a.key)) reason = `unknown_attribute:${a && a.key}`;
      else if (seen.has(a.key)) reason = 'duplicate_attribute';
      else if (!LEVELS.has(a.level)) reason = `bad_level:${a.level}`;
      else if (!OWNERS.has(a.owner)) reason = `bad_owner:${a.owner}`;
      if (reason) {
        bad('attribute_sets', k, reason, a);
        return;
      }
      seen.add(a.key);
      const axisIndex = axes.indexOf(a.key);
      sets.push({
        node_id: nodeId,
        attribute_key: a.key,
        level: a.level,
        owner: a.owner,
        per_variant: axisIndex >= 0 || bool(a.per_variant),
        filterable: bool(a.filterable),
        axis_order: axisIndex >= 0 ? axisIndex + 1 : null,
        in_basic_form: basic.has(a.key),
        sort_order: i,
        note: textOrNull(a.note),
        source: SOURCE,
      });
    });
    for (const axis of axes) {
      if (!seen.has(axis)) bad('attribute_sets', `${subKey}.${axis}`, 'axis_not_in_set', s);
    }
    for (const key of basic) {
      if (!seen.has(key)) bad('attribute_sets', `${subKey}.${key}`, 'basic_field_not_in_set', s);
    }
  }

  return {
    entities: { attribute_definitions: definitions, attribute_sets: sets },
    rejects,
    review: [],
    inputCount: Object.keys(input.definitions || {}).length + Object.keys(input.sets || {}).length,
    notes: {
      definitions: definitions.length,
      shop_types: Object.keys(input.sets || {}).length,
      set_rows: sets.length,
      variant_axes: sets.filter((r) => r.axis_order).length,
    },
  };
}

module.exports = { meta, entities, extract, transform };
